// ---- Small building blocks ---------------------------------------------


function TypedLines({ lines, speed = 55, startDelay = 300 }) {
  const [visible, setVisible] = useState(0);
  const [charCount, setCharCount] = useState(0);
  useEffect(() => {
    let cancelled = false;
    let timeout;
    function typeLine(lineIdx, charIdx) {
      if (cancelled) return;
      if (lineIdx >= lines.length) return;
      const line = lines[lineIdx];
      if (charIdx <= line.length) {
        setVisible(lineIdx);
        setCharCount(charIdx);
        timeout = setTimeout(() => typeLine(lineIdx, charIdx + 1), speed);
      } else {
        timeout = setTimeout(() => typeLine(lineIdx + 1, 0), 380);
      }
    }
    timeout = setTimeout(() => typeLine(0, 0), startDelay);
    return () => {
      cancelled = true;
      clearTimeout(timeout);
    };
  }, [lines, speed, startDelay]);

  return (
    <div style={{ fontFamily: MONO, fontSize: 15, lineHeight: 1.9 }}>
      {lines.map((line, i) => {
        if (i > visible) return null;
        const text = i === visible ? line.slice(0, charCount) : line;
        const done = i < visible || (i === visible && charCount >= line.length);
        return (
          <div key={i} style={{ color: i % 2 === 0 ? C.mutedDim : C.text }}>
            {text}
            {i === visible && !done && (
              <span style={{ display: "inline-block", width: 8, height: 16, background: C.amber, marginLeft: 2, verticalAlign: "-2px" }} />
            )}
          </div>
        );
      })}
    </div>
  );
}

function SectionLabel({ n, children }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 22 }}>
      <span style={{ fontFamily: MONO, fontSize: 12, color: C.amber, letterSpacing: 1 }}>[{n}]</span>
      <span style={{ fontFamily: MONO, fontSize: 12, color: C.muted, textTransform: "uppercase", letterSpacing: 2 }}>{children}</span>
      <div style={{ flex: 1, height: 1, background: C.border }} />
    </div>
  );
}

const badgeColor = (c) => (c === "amber" ? C.amber : c === "blue" ? C.blue : C.mutedDim);

